export function applyDiscount(totalPaise, pct) {
  const discount = Math.round((totalPaise * pct) / 100);
  const total = totalPaise - discount;
  return total;
}

export function lineTotal(unitPaise, qty) {
  const total = unitPaise * qty;
  return total;
}

export function formatPrice(paise) {
  const rupees = Math.floor(paise / 100);
  const rest = String(paise % 100).padStart(2, "0");
  const total = "₹" + rupees.toLocaleString("en-IN") + "." + rest;
  return total;
}
